14	/**
15	 * Runs TreeGuard analysis from resolved CLI options.
16	 */
17	final class TreeGuardAnalysisRunner
18	{
19	    /** @readonly */
20	    private TreeGuardConfigPathResolver $pathResolver;
21	
22	    /** @readonly */
23	    private TreeGuardReporterOverride $reporterOverride;
24	
25	    /**
26	     * Creates an analysis runner from TreeGuard services.
27	     */
28	    public function __construct(
29	        /** @readonly */
30	        private string $workingDirectory,
31	        /** @readonly */
32	        private ConfigLoader $configLoader,
33	        /** @readonly */
34	        private TreeGuardAnalyzer $analyzer,
35	        /** @readonly */
36	        private ReporterFactory $reporterFactory,
37	        /** @readonly */
38	        private TreeGuardOutputWriter $writer,
39	        ?TreeGuardConfigPathResolver $pathResolver = null,
40	        ?TreeGuardReporterOverride $reporterOverride = null,
41	    ) {
42	        $this->pathResolver = $pathResolver ?? new TreeGuardConfigPathResolver();
43	        $this->reporterOverride = $reporterOverride ?? new TreeGuardReporterOverride();
44	    }
45	
46	    /**
47	     * Runs analysis and writes the selected report.
48	     */
49	    public function run(string $configPath, ?string $reporterOverride): int
50	    {
51	        try {
52	            $config = $this->configLoader->load($this->pathResolver->resolve($this->workingDirectory, $configPath));
53	            $config = $this->reporterOverride->apply($config, $reporterOverride);
54	            $result = $this->analyzer->analyze($config);
55	            $reporter = $this->reporterFactory->create($config->report->reporter);
56	        } catch (TreeGuardException $exception) {
57	            $this->writer->writeError(sprintf("TreeGuard error: %s\n", $exception->getMessage()));
58	
59	            return 2;
60	        }
61	
62	        $this->writer->write($reporter->report($result, $config->report));
63	
64	        return $result->hasViolations() ? 1 : 0;
65	    }
