9	use Toolkit\TreeGuard\TreeGuardException;
10	
11	/**
12	 * Parses TreeGuard command-line arguments.
13	 */
14	final class TreeGuardCliArgumentParser
15	{
16	    /**
17	     * Parses TreeGuard flags and options.
18	     *
19	     * @param list<string> $argv
20	     * @return array{config: string, help: bool, reporter: ?string, version: bool}
21	     *
22	     * @throws TreeGuardException when an option is unknown or missing its value
23	     */
24	    public function parse(array $argv): array
25	    {
26	        $arguments = ['config' => 'tree.yaml', 'help' => false, 'reporter' => null, 'version' => false];
27	        $skipNext = false;
28	
29	        foreach ($argv as $index => $arg) {
30	            if ($skipNext) {
31	                $skipNext = false;
32	                continue;
33	            }
34	
35	            if ($arg === '--help' || $arg === '-h') {
36	                $arguments['help'] = true;
37	            } elseif ($arg === '--version' || $arg === '-V') {
38	                $arguments['version'] = true;
39	            } elseif ($arg === '--config') {
40	                if (!isset($argv[$index + 1]) || str_starts_with($argv[$index + 1], '-')) {
41	                    throw new TreeGuardException(sprintf('Missing value for %s.', '--config'));
42	                }
43	                $arguments['config'] = $argv[$index + 1];
44	                $skipNext = true;
45	            } elseif (str_starts_with($arg, '--config=')) {
46	                $arguments['config'] = substr($arg, 9);
47	            } elseif ($arg === '--reporter' || $arg === '--format') {
48	                if (!isset($argv[$index + 1]) || str_starts_with($argv[$index + 1], '-')) {
49	                    throw new TreeGuardException(sprintf('Missing value for %s.', $arg));
50	                }
51	                $arguments['reporter'] = $argv[$index + 1];
52	                $skipNext = true;
53	            } elseif (str_starts_with($arg, '--reporter=')) {
54	                $arguments['reporter'] = substr($arg, 11);
55	            } elseif (str_starts_with($arg, '--format=')) {
56	                $arguments['reporter'] = substr($arg, 9);
57	            } else {
58	                throw new TreeGuardException(sprintf('Unknown option: %s', $arg));
59	            }
60	        }
61	
62	        return $arguments;
63	    }
64	}
