17	/**
18	 * Reads scalar values from tree.yaml mappings with contextual error messages.
19	 */
20	final class ConfigScalarReader
21	{
22	    /** @var list<string> */
23	    private const CASES = ['pascal', 'camel', 'snake', 'kebab'];
24	
25	    /**
26	     * Reads a required or defaulted non-empty string value.
27	     *
28	     * @param array<mixed> $data
29	     *
30	     * @throws TreeGuardException when the value is not a non-empty string
31	     */
32	    public function string(array $data, string $key, ?string $default, string $context): string
33	    {
34	        $value = $data[$key] ?? $default;
35	        if (!is_string($value) || $value === '') {
36	            throw new TreeGuardException(sprintf('Invalid tree.yaml: "%s" must be a non-empty string.', $this->label($context, $key)));
37	        }
38	
39	        return $value;
40	    }
41	
42	    /**
43	     * Reads a boolean value with a default.
44	     *
45	     * @param array<mixed> $data
46	     *
47	     * @throws TreeGuardException when the value is not a boolean
48	     */
49	    public function bool(array $data, string $key, bool $default, string $context): bool
50	    {
51	        $value = $data[$key] ?? $default;
52	        if (!is_bool($value)) {
53	            throw new TreeGuardException(sprintf('Invalid tree.yaml: "%s" must be a boolean.', $this->label($context, $key)));
54	        }
55	
56	        return $value;
57	    }
58	
59	    /**
60	     * Reads an optional positive integer value, returning null when absent.
61	     *
62	     * @param array<mixed> $data
63	     *
64	     * @throws TreeGuardException when the value is not a positive integer
65	     */
66	    public function optionalPositiveInt(array $data, string $key, string $context): ?int
67	    {
68	        if (!array_key_exists($key, $data)) {
69	            return null;
70	        }
71	
72	        $value = $data[$key];
73	        if (!is_int($value) || $value < 1) {
74	            throw new TreeGuardException(sprintf('Invalid tree.yaml: "%s" must be a positive integer.', $this->label($context, $key)));
75	        }
76	
77	        return $value;
78	    }
79	
80	    /**
81	     * Reads an optional naming convention value, returning null when absent.
82	     *
83	     * @param array<mixed> $data
84	     *
85	     * @throws TreeGuardException when the value is not a supported naming convention
86	     */
87	    public function optionalCase(array $data, string $key, string $context): ?string
88	    {
89	        if (!array_key_exists($key, $data)) {
90	            return null;
91	        }
92	
93	        $value = $data[$key];
94	        if (!is_string($value) || !in_array($value, self::CASES, true)) {
95	            throw new TreeGuardException(sprintf('Invalid tree.yaml: "%s" must be one of: %s.', $this->label($context, $key), implode(', ', self::CASES)));
96	        }
97	
98	        return $value;
99	    }
100	
101	    /**
102	     * Returns the fully qualified key label used in error messages.
103	     */
104	    public function label(string $context, string $key): string
105	    {
106	        return $context === '' ? $key : $context . '.' . $key;
107	    }
108	}
