14	/**
15	 * Reads string lists from tree.yaml mappings with contextual error messages.
16	 */
17	final class ConfigStringListReader
18	{
19	    /**
20	     * Reads a list of non-empty strings, applying the default when absent.
21	     *
22	     * @param array<mixed> $data
23	     * @param list<string> $default
24	     * @return list<string>
25	     *
26	     * @throws TreeGuardException when the value is not a list of non-empty strings
27	     */
28	    public function read(array $data, string $key, array $default, string $context): array
29	    {
30	        $value = $data[$key] ?? $default;
31	        if (!is_array($value)) {
32	            throw new TreeGuardException(sprintf('Invalid tree.yaml: "%s" must be a list of strings.', $this->label($context, $key)));
33	        }
34	
35	        $strings = [];
36	        foreach ($value as $entry) {
37	            if (!is_string($entry) || $entry === '') {
38	                throw new TreeGuardException(sprintf('Invalid tree.yaml: "%s" must be a list of strings.', $this->label($context, $key)));
39	            }
40	            $strings[] = $entry;
41	        }
42	
43	        return $strings;
44	    }
45	
46	    /**
47	     * Reads an optional list of non-empty strings, returning null when the key is absent.
48	     *
49	     * @param array<mixed> $data
50	     * @return ?list<string>
51	     *
52	     * @throws TreeGuardException when the value is not a list of non-empty strings
53	     */
54	    public function readOptional(array $data, string $key, string $context): ?array
55	    {
56	        if (!array_key_exists($key, $data)) {
57	            return null;
58	        }
59	
60	        if ($data[$key] === null) {
61	            throw new TreeGuardException(sprintf('Invalid tree.yaml: "%s" must be a list of strings.', $this->label($context, $key)));
62	        }
63	
64	        return $this->read($data, $key, [], $context);
65	    }
66	
67	    /**
68	     * Returns the fully qualified key label used in error messages.
69	     */
70	    public function label(string $context, string $key): string
71	    {
72	        return $context === '' ? $key : $context . '.' . $key;
73	    }
74	}
