13	
14	/**
15	 * Reads TreeGuard report configuration from tree.yaml.
16	 */
17	final class ReportConfigReader
18	{
19	    /** @var list<string> */
20	    private const REPORTERS = ['ai', 'text', 'json'];
21	
22	    /** @var list<string> */
23	    private const ORDER_FIELDS = ['path', 'rule', 'actual', 'limit'];
24	
25	    /** @readonly */
26	    private ConfigScalarReader $scalarReader;
27	
28	    /** @readonly */
29	    private ConfigStringListReader $stringListReader;
30	
31	    /**
32	     * Creates a reader from scalar and list validation.
33	     */
34	    public function __construct(
35	        ?ConfigScalarReader $scalarReader = null,
36	        ?ConfigStringListReader $stringListReader = null,
37	    ) {
38	        $this->scalarReader = $scalarReader ?? new ConfigScalarReader();
39	        $this->stringListReader = $stringListReader ?? new ConfigStringListReader();
40	    }
41	
42	    /**
43	     * Reads report output configuration.
44	     *
45	     * @param mixed $value
46	     *
47	     * @throws TreeGuardException when the report section is not a mapping or contains unsupported values
48	     */
49	    public function read($value): ReportConfig
50	    {
51	        if (!is_array($value)) {
52	            throw new TreeGuardException('Invalid tree.yaml: "report" must be a mapping.');
53	        }
54	
55	        $reporter = $this->scalarReader->string($value, 'reporter', 'ai', 'report');
56	        if (!in_array($reporter, self::REPORTERS, true)) {
57	            throw new TreeGuardException(sprintf('Invalid tree.yaml: "report.reporter" must be one of: %s.', implode(', ', self::REPORTERS)));
58	        }
59	
60	        $orderBy = $this->stringListReader->read($value, 'order_by', ['path', 'rule'], 'report');
61	        foreach ($orderBy as $field) {
62	            if (!in_array($field, self::ORDER_FIELDS, true)) {
63	                throw new TreeGuardException(sprintf('Invalid tree.yaml: "report.order_by" contains unsupported field "%s".', $field));
64	            }
65	        }
66	
67	        return new ReportConfig($reporter, $orderBy);
68	    }
69	}
