14	/**
15	 * Reads one tree.yaml rule block, rejecting unknown keys so that a typo
16	 * cannot silently disable a constraint.
17	 */
18	final class RuleConfigReader
19	{
20	    /** @var list<string> */
21	    private const KNOWN_KEYS = [
22	        'path',
23	        'max_files',
24	        'max_dirs',
25	        'max_total_files',
26	        'max_depth',
27	        'allow',
28	        'deny',
29	        'allow_dirs',
30	        'deny_dirs',
31	        'require',
32	        'forbid_empty',
33	        'file_case',
34	        'dir_case',
35	    ];
36	
37	    /** @readonly */
38	    private ConfigScalarReader $scalarReader;
39	
40	    /** @readonly */
41	    private ConfigStringListReader $stringListReader;
42	
43	    /**
44	     * Creates a reader from scalar and list validation.
45	     */
46	    public function __construct(
47	        ?ConfigScalarReader $scalarReader = null,
48	        ?ConfigStringListReader $stringListReader = null,
49	    ) {
50	        $this->scalarReader = $scalarReader ?? new ConfigScalarReader();
51	        $this->stringListReader = $stringListReader ?? new ConfigStringListReader();
52	    }
53	
54	    /**
55	     * Reads one rule block at the given list index.
56	     *
57	     * @param mixed $value
58	     *
59	     * @throws TreeGuardException when the rule block is not a mapping or contains unsupported keys
60	     */
61	    public function read($value, int $index): RuleConfig
62	    {
63	        $context = sprintf('rules[%d]', $index);
64	        if (!is_array($value)) {
65	            throw new TreeGuardException(sprintf('Invalid tree.yaml: "%s" must be a mapping.', $context));
66	        }
67	
