15	{
16	    /** @readonly */
17	    private LocGuardCliValueOptionParser $valueOptionParser;
18	
19	    /**
20	     * Creates an argument parser from value-option parsing behavior.
21	     */
22	    public function __construct(?LocGuardCliValueOptionParser $valueOptionParser = null)
23	    {
24	        $this->valueOptionParser = $valueOptionParser ?? new LocGuardCliValueOptionParser();
25	    }
26	
27	    /**
28	     * Parses LocGuard flags and options.
29	     *
30	     * @param list<string> $argv
31	     * @return array{config: string, explain: ?string, help: bool, reporter: ?string, version: bool}
32	     *
33	     * @throws LocGuardException when an option is unknown or missing its value
34	     */
35	    public function parse(array $argv): array
36	    {
37	        $arguments = ['config' => 'loc.yaml', 'explain' => null, 'help' => false, 'reporter' => null, 'version' => false];
38	        $skipNext = false;
39	
40	        foreach ($argv as $index => $arg) {
41	            if ($skipNext) {
42	                $skipNext = false;
43	                continue;
44	            }
45	
46	            $valueOption = $this->valueOptionParser->parse($argv, $index);
47	            if ($valueOption !== null) {
48	                if ($valueOption->key === 'config') {
49	                    $arguments['config'] = $valueOption->value;
50	                } elseif ($valueOption->key === 'explain') {
51	                    $arguments['explain'] = $valueOption->value;
52	                } else {
53	                    $arguments['reporter'] = $valueOption->value;
54	                }
55	                $skipNext = $valueOption->consumesNext;
56	            } elseif ($arg === '--help' || $arg === '-h') {
57	                $arguments['help'] = true;
58	            } elseif ($arg === '--version' || $arg === '-V') {
59	                $arguments['version'] = true;
60	            } else {
61	                throw new LocGuardException(sprintf('Unknown option: %s', $arg));
62	            }
63	        }
64	
65	        return $arguments;
66	    }
67	}
