    if (isset(self::FLAGS[$arg])) {
        $flags[self::FLAGS[$arg]] = true;
        continue;
    }

    $parts = explode('=', $arg, 2);
    $name = $parts[0];
    $value = $parts[1] ?? null;
    if (isset(self::VALUE_OPTIONS[$name])) {
        if ($value === null) {
            $value = $argv[$index + 1] ?? null;
            if ($value === null || str_starts_with($value, '-')) {
                throw new DocGuardException(sprintf('Missing value for %s.', $name));
            }
            $index++;
        }
